package com.hrflow.controller;
import com.hrflow.entity.*;import com.hrflow.repository.*;import lombok.RequiredArgsConstructor;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/jobs") @RequiredArgsConstructor class JobController{final JobRepository r;@GetMapping List<Job> all(){return r.findAll();}@PostMapping @PreAuthorize("hasAnyRole('ADMIN','HR')")Job add(@RequestBody Job x){return r.save(x);}@PutMapping("/{id}")@PreAuthorize("hasAnyRole('ADMIN','HR')")Job edit(@PathVariable Long id,@RequestBody Job x){x.setId(id);return r.save(x);}@DeleteMapping("/{id}")@PreAuthorize("hasAnyRole('ADMIN','HR')")void del(@PathVariable Long id){r.deleteById(id);}}
@RestController @RequestMapping("/api/candidates") @RequiredArgsConstructor class CandidateController{final CandidateRepository r;@GetMapping List<Candidate> all(){return r.findAll();}@PostMapping @PreAuthorize("hasAnyRole('ADMIN','HR')")Candidate add(@RequestBody Candidate x){return r.save(x);}@PutMapping("/{id}")@PreAuthorize("hasAnyRole('ADMIN','HR')")Candidate edit(@PathVariable Long id,@RequestBody Candidate x){x.setId(id);return r.save(x);}}
@RestController @RequestMapping("/api/interviews") @RequiredArgsConstructor class InterviewController{final InterviewRepository r;@GetMapping List<Interview> all(){return r.findAll();}@PostMapping @PreAuthorize("hasAnyRole('ADMIN','HR','MANAGER')")Interview add(@RequestBody Interview x){return r.save(x);}@PutMapping("/{id}")@PreAuthorize("hasAnyRole('ADMIN','HR','MANAGER')")Interview edit(@PathVariable Long id,@RequestBody Interview x){x.setId(id);return r.save(x);}}
@RestController @RequestMapping("/api/performance") @RequiredArgsConstructor class PerformanceController{final GoalRepository goals;final PerformanceReviewRepository reviews;@GetMapping("/goals")List<Goal> goals(@RequestParam(required=false)Long employeeId){return employeeId==null?goals.findAll():goals.findByEmployeeId(employeeId);}@PostMapping("/goals")@PreAuthorize("hasAnyRole('ADMIN','HR','MANAGER')")Goal addGoal(@RequestBody Goal x){return goals.save(x);}@PutMapping("/goals/{id}")Goal editGoal(@PathVariable Long id,@RequestBody Goal x){x.setId(id);return goals.save(x);}@GetMapping("/reviews")List<PerformanceReview> reviews(@RequestParam(required=false)Long employeeId){return employeeId==null?reviews.findAll():reviews.findByEmployeeId(employeeId);}@PostMapping("/reviews")@PreAuthorize("hasAnyRole('ADMIN','HR','MANAGER')")PerformanceReview addReview(@RequestBody PerformanceReview x){return reviews.save(x);}}
@RestController @RequestMapping("/api/announcements") @RequiredArgsConstructor class AnnouncementController{final AnnouncementRepository r;@GetMapping List<Announcement> all(){return r.findAll();}@PostMapping @PreAuthorize("hasAnyRole('ADMIN','HR')")Announcement add(@RequestBody Announcement x){return r.save(x);}@PutMapping("/{id}")@PreAuthorize("hasAnyRole('ADMIN','HR')")Announcement edit(@PathVariable Long id,@RequestBody Announcement x){x.setId(id);return r.save(x);}}
@RestController @RequestMapping("/api/notifications") @RequiredArgsConstructor class NotificationController{final NotificationRepository r;@GetMapping("/user/{id}")List<Notification> user(@PathVariable Long id){return r.findByUserIdOrderByCreatedAtDesc(id);}@PutMapping("/{id}/read")Notification read(@PathVariable Long id){Notification n=r.findById(id).orElseThrow();n.setReadFlag(true);return r.save(n);}}
@RestController @RequestMapping("/api/tasks") @RequiredArgsConstructor class TaskController{final TaskRepository r;@GetMapping List<Task> all(@RequestParam(required=false)Long employeeId){return employeeId==null?r.findAll():r.findByEmployeeId(employeeId);}@PostMapping @PreAuthorize("hasAnyRole('ADMIN','HR','MANAGER')")Task add(@RequestBody Task x){return r.save(x);}@PutMapping("/{id}")Task edit(@PathVariable Long id,@RequestBody Task x){x.setId(id);return r.save(x);}}
@RestController @RequestMapping("/api/documents") @RequiredArgsConstructor class DocumentController{final DocumentRepository r;@GetMapping List<Document> all(@RequestParam(required=false)Long employeeId){return employeeId==null?r.findAll():r.findByEmployeeId(employeeId);}@PostMapping @PreAuthorize("hasAnyRole('ADMIN','HR','MANAGER','EMPLOYEE')")Document add(@RequestBody Document x){return r.save(x);}@DeleteMapping("/{id}")@PreAuthorize("hasAnyRole('ADMIN','HR')")void del(@PathVariable Long id){r.deleteById(id);}}
